import SwiftUI

/// The marks that name each agent, on a 24pt grid. OpenAI and Claude come from
/// Simple Icons (CC0). They identify the services only; see the README.
public struct AgentLogo: Shape {
    let kind: AgentKind

    public init(_ kind: AgentKind) {
        self.kind = kind
    }

    public func path(in rect: CGRect) -> Path {
        let scale = min(rect.width, rect.height) / 24
        return Self.parse(Self.data(kind))
            .applying(CGAffineTransform(scaleX: scale, y: scale))
            .offsetBy(dx: rect.midX - 12 * scale, dy: rect.midY - 12 * scale)
    }

    /// Absolute M, L, C and Z only, as the data below is written.
    static func parse(_ data: String) -> Path {
        var path = Path()
        var command: Character = "M"
        var numbers: [CGFloat] = []
        func flush() {
            switch command {
            case "M" where numbers.count == 2: path.move(to: CGPoint(x: numbers[0], y: numbers[1]))
            case "L" where numbers.count == 2: path.addLine(to: CGPoint(x: numbers[0], y: numbers[1]))
            case "C" where numbers.count == 6:
                path.addCurve(to: CGPoint(x: numbers[4], y: numbers[5]),
                              control1: CGPoint(x: numbers[0], y: numbers[1]),
                              control2: CGPoint(x: numbers[2], y: numbers[3]))
            case "Z": path.closeSubpath()
            default: break
            }
            numbers = []
        }
        var token = ""
        for character in data {
            if character.isLetter || character == " " {
                if let value = Double(token) { numbers.append(CGFloat(value)) }
                token = ""
                if character.isLetter {
                    flush()
                    command = character
                }
            } else {
                token.append(character)
            }
        }
        if let value = Double(token) { numbers.append(CGFloat(value)) }
        flush()
        return path
    }

    private static func data(_ kind: AgentKind) -> String {
        switch kind {
        case .codex: return openAI
        case .claude: return claude
        case .grok: return xAI
        }
    }

